WITH fo AS MATERIALIZED (SELECT o.id,o.customer_id,o.created_at FROM orders o WHERE lower(o.status)='completed' AND o.created_at::date>=DATE '2024-01-01'), co AS MATERIALIZED (SELECT fo.id,fo.customer_id FROM fo WHERE EXISTS (SELECT 1 FROM payments pay WHERE pay.order_id=fo.id AND pay.status='captured')), eligible AS (SELECT DISTINCT fo.customer_id FROM fo JOIN order_items oi ON oi.order_id=fo.id JOIN products p ON p.id=oi.product_id AND p.active JOIN product_suppliers ps ON ps.product_id=p.id JOIN suppliers s ON s.id=ps.supplier_id AND s.risk_tier>=4 JOIN shipments sh ON sh.order_id=fo.id WHERE sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days'), lasts AS (SELECT customer_id,max(created_at) last_completed_at FROM fo GROUP BY customer_id), cap_counts AS (SELECT customer_id,count(*) captured_order_count FROM co GROUP BY customer_id), revenues AS (SELECT co.customer_id,sum((oi.quantity-COALESCE(r.quantity,0))*oi.unit_price) net_item_revenue FROM co JOIN order_items oi ON oi.order_id=co.id LEFT JOIN returns r ON r.order_id=oi.order_id AND r.line_no=oi.line_no GROUP BY co.customer_id), promos AS (SELECT fo.customer_id,sum(op.discount_amount) active_promotion_discount FROM fo JOIN order_promotions op ON op.order_id=fo.id JOIN promotions pr ON pr.id=op.promotion_id WHERE pr.active GROUP BY fo.customer_id), lates AS (SELECT fo.customer_id,count(*) late_shipment_count FROM fo JOIN shipments sh ON sh.order_id=fo.id WHERE sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days' GROUP BY fo.customer_id), risks AS (SELECT fo.customer_id,count(DISTINCT ps.supplier_id) risky_supplier_count FROM fo JOIN order_items oi ON oi.order_id=fo.id JOIN product_suppliers ps ON ps.product_id=oi.product_id JOIN suppliers s ON s.id=ps.supplier_id WHERE s.risk_tier>=4 GROUP BY fo.customer_id) SELECT c.id customer_id,c.region,c.segment,COALESCE(cc.captured_order_count,0::bigint) captured_order_count,COALESCE(rv.net_item_revenue,0)::numeric(20,2) net_item_revenue,COALESCE(pm.active_promotion_discount,0)::numeric(18,2) active_promotion_discount,COALESCE(lt.late_shipment_count,0::bigint) late_shipment_count,COALESCE(rk.risky_supplier_count,0::bigint) risky_supplier_count,la.last_completed_at FROM customers c JOIN eligible e ON e.customer_id=c.id LEFT JOIN lasts la ON la.customer_id=c.id LEFT JOIN cap_counts cc ON cc.customer_id=c.id LEFT JOIN revenues rv ON rv.customer_id=c.id LEFT JOIN promos pm ON pm.customer_id=c.id LEFT JOIN lates lt ON lt.customer_id=c.id LEFT JOIN risks rk ON rk.customer_id=c.id WHERE c.active